from pathlib import Path
import re, gzip, base64
ROOT=Path(__file__).resolve().parents[1]
JAVA_PATH=ROOT/"app/src/main/java/br/com/treinodabine/MainActivity.java"
ASSETS=ROOT/"app/src/main/assets"
BUILD=ROOT/"app/build.gradle"
JAVA_GZ=""
HTML_GZ=""
JAVA_PATH.parent.mkdir(parents=True,exist_ok=True)
ASSETS.mkdir(parents=True,exist_ok=True)
JAVA_PATH.write_bytes(gzip.decompress(base64.b64decode(JAVA_GZ)))
(ASSETS/"index.html").write_bytes(gzip.decompress(base64.b64decode(HTML_GZ)))
text=BUILD.read_text(encoding="utf-8")
text=re.sub(r"versionCode\s+\d+","versionCode 5",text)
text=re.sub(r"versionName\s+'[^']+'","versionName '5.0'",text)
BUILD.write_text(text,encoding="utf-8")
print("Treino da Bine v5 aplicado")
